class Solution {
  public long maxProduct(String s) {
    int n = s.length();
    char[] c = s.toCharArray();
    // Manacher: d[i] = number of odd palindromes centred at i
    int[] d = new int[n];
    for (int i = 0, l = 0, r = -1; i < n; i++) {
      int k = i > r ? 1 : Math.min(d[l + r - i], r - i + 1);
      while (i - k >= 0 && i + k < n && c[i - k] == c[i + k]) k++;
      d[i] = k;
      if (i + k - 1 > r) {
        l = i - k + 1;
        r = i + k - 1;
      }
    }
    int[] endingAt = new int[n], startingAt = new int[n];
    for (int i = 0; i < n; i++) {
      endingAt[i + d[i] - 1] = Math.max(endingAt[i + d[i] - 1], 2 * d[i] - 1);
      startingAt[i - d[i] + 1] = Math.max(startingAt[i - d[i] + 1], 2 * d[i] - 1);
    }
    // a palindrome ending at i + 1 shrinks (by 2) to one ending at i, and likewise for starts
    for (int i = n - 2; i >= 0; i--) endingAt[i] = Math.max(endingAt[i], endingAt[i + 1] - 2);
    for (int i = 1; i < n; i++) startingAt[i] = Math.max(startingAt[i], startingAt[i - 1] - 2);
    int[] prefix = new int[n], suffix = new int[n];
    for (int i = 0; i < n; i++) prefix[i] = Math.max(i > 0 ? prefix[i - 1] : 0, endingAt[i]);
    for (int i = n - 1; i >= 0; i--)
      suffix[i] = Math.max(i + 1 < n ? suffix[i + 1] : 0, startingAt[i]);
    long best = 0;
    for (int i = 0; i + 1 < n; i++) best = Math.max(best, (long) prefix[i] * suffix[i + 1]);
    return best;
  }
}
